const zoneRow = ($('Step 3: Read the zone sheet').first().json.items || [])
  .find(z => (z.postcodes || []).some(p => lower(p).replace(/\s+/g, '') === postcode && postcode));
const zone = zoneRow ? zoneRow.zone : null;
